const j = $json;
return {
  json: {
    message_id: j.id,
    subject: j.subject || '',
    from_text: (j.from && j.from.text) || '',
    body_text: j.text || j.html || ''
  }
};

const j = $json;
const SYSTEM_MESSAGE = `You classify emails for a job-hunting tracker. Read the email and respond with STRICT JSON ONLY, matching exactly this shape, no other text, no markdown fences:
{
  "classification": "oa" | "interview" | "rejection" | "offer" | "referral" | "other",
  "company": "<string, the hiring company this email is about, or null>",
  "role": "<string, the job title/role mentioned, or null>",
  "deadline": "<string, exactly as stated (e.g. an interview date/time, a response-by date), or null if none stated>"
}

Classification guide:
- oa: online assessment / coding test invitation
- interview: interview invitation or scheduling
- rejection: application rejected / role filled / not moving forward
- offer: job offer extended
- referral: someone offering or requesting a referral
- other: anything not clearly one of the above (newsletters, unrelated personal email, spam, etc.) -- use this whenever genuinely unsure rather than forcing a guess

company, role, and deadline are extracted verbatim from the email text, never inferred or guessed.`;

const userMessage = `SUBJECT: ${j.subject || ''}
FROM: ${j.from_text || ''}

BODY:
${(j.body_text || '').slice(0, 6000)}`;

return { json: { ...j, system_message: SYSTEM_MESSAGE, user_message: userMessage } };

const VALID = ['oa', 'interview', 'rejection', 'offer', 'referral', 'other'];

function tryValidate(rawText) {
  let parsed;
  try {
    const cleaned = (rawText || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    return { ok: false, error: 'JSON parse error: ' + e.message };
  }
  const errors = [];
  if (!VALID.includes(parsed.classification)) errors.push('classification must be one of ' + VALID.join('/'));
  if (parsed.company !== null && parsed.company !== undefined && typeof parsed.company !== 'string') errors.push('company must be a string or null');
  if (parsed.role !== null && parsed.role !== undefined && typeof parsed.role !== 'string') errors.push('role must be a string or null');
  if (parsed.deadline !== null && parsed.deadline !== undefined && typeof parsed.deadline !== 'string') errors.push('deadline must be a string or null');
  if (errors.length) return { ok: false, error: errors.join('; ') };
  return { ok: true, parsed };
}

const resp = $json;
const ctx = $('Check Already Processed').all()[$itemIndex].json;
const content = resp.content || [];
const textBlock = content.find(b => b.type === 'text');
const rawText = textBlock ? textBlock.text : '';
const result = tryValidate(rawText);

return {
  json: {
    message_id: ctx.message_id,
    subject: ctx.subject,
    from_text: ctx.from_text,
    valid: result.ok,
    classification: result.ok ? result.parsed.classification : null,
    company: result.ok ? (result.parsed.company || null) : null,
    role: result.ok ? (result.parsed.role || null) : null,
    deadline: result.ok ? (result.parsed.deadline || null) : null,
    retry_user_message: result.ok ? null : ($('Build Classify Prompt').all()[$itemIndex].json.user_message + '\n\nYour previous response was invalid and could not be used: ' + result.error + '\nRespond again with STRICT JSON ONLY, matching exactly the required shape, no other text, no markdown fences.'),
    system_message: $('Build Classify Prompt').all()[$itemIndex].json.system_message
  }
};

const VALID = ['oa', 'interview', 'rejection', 'offer', 'referral', 'other'];

function tryValidate(rawText) {
  let parsed;
