}

const resp = $json;
const ctx = $('Validate Attempt 1').all()[$itemIndex].json;
const content = resp.content || [];
const textBlock = content.find(b => b.type === 'text');
const rawText = textBlock ? textBlock.text : '';
const result = tryValidate(rawText);

return {
  json: {
    message_id: ctx.message_id,
    subject: ctx.subject,
    from_text: ctx.from_text,
    classification: result.ok ? result.parsed.classification : 'other',
    company: result.ok ? (result.parsed.company || null) : null,
    role: result.ok ? (result.parsed.role || null) : null,
    deadline: result.ok ? (result.parsed.deadline || null) : null,
    invalid: !result.ok
  }
};

const LEGAL_SUFFIXES = ['private limited', 'pvt ltd', 'pvt', 'pte ltd', 'llp', 'llc', 'incorporated', 'inc', 'technologies', 'technology', 'labs', 'corporation', 'corp', 'limited', 'ltd', 'gmbh'];

function normCompany(raw) {
  let s = (raw || '').toLowerCase().trim();
  s = s.replace(/[.,]/g, '');
  for (const suffix of LEGAL_SUFFIXES) {
    const re = new RegExp('\\b' + suffix + '\\b', 'g');
    s = s.replace(re, '');
  }
  return s.replace(/\s+/g, ' ').trim();
}

return { json: { ...$json, norm_company_query: normCompany($json.company) } };

const ctx = $('Normalize Company For Match').all()[$itemIndex].json;
const match = $json;
return {
  json: {
    message_id: ctx.message_id,
    subject: ctx.subject,
    from_text: ctx.from_text,
    classification: ctx.classification,
    company: ctx.company,
    role: ctx.role,
    deadline: ctx.deadline,
    invalid: ctx.invalid || false,
    matched_posting_id: match.matched_posting_id || null,
    matched_company: match.matched_company || null,
    match_similarity: match.match_similarity || null
  }
};

const j = $json;
const LABELS = { oa: '\uD83D\uDCDD Online Assessment', interview: '\uD83C\uDFA4 Interview', rejection: '\u274C Rejection', offer: '\uD83C\uDF89 Offer', referral: '\uD83E\uDD1D Referral' };
const title = `${LABELS[j.classification] || j.classification} \u2014 ${j.company || 'Unknown company'}`;

const lines = [
  j.role ? `**Role:** ${j.role}` : null,
  j.deadline ? `**Date/Deadline:** ${j.deadline}` : null,
  j.matched_posting_id
    ? `**Matched posting:** ${j.matched_company} (similarity ${Math.round((j.match_similarity || 0) * 100)}%)`
    : '**No matching tracked posting found** \u2014 update manually if this is relevant.',
  `**Subject:** ${j.subject}`,
  `**From:** ${j.from_text}`
].filter(Boolean);

const color = { oa: 15105570, interview: 3066993, rejection: 15548997, offer: 3066993, referral: 3447003 }[j.classification] || 9807270;

return { json: { ...j, embed_title: title, embed_description: lines.join('\n'), embed_color: color } };

let fetched = 0, notified = 0;
try { fetched = $('Check Already Processed').all().length; } catch (e) {}
try { notified = $('Send Discord Alert').all().length; } catch (e) {}
const processed = $input.all().length;
return [{ json: { fetched, processed, notified } }];
